SELECT employee_id FROM (
  SELECT e.employee_id AS employee_id FROM Employees e LEFT JOIN Salaries s ON e.employee_id = s.employee_id WHERE s.employee_id IS NULL
  UNION
  SELECT s.employee_id AS employee_id FROM Salaries s LEFT JOIN Employees e ON e.employee_id = s.employee_id WHERE e.employee_id IS NULL
)
ORDER BY employee_id;

WITH top_students AS (SELECT user_id FROM course_completions GROUP BY user_id HAVING COUNT(*) >= 5 AND AVG(course_rating) >= 4),
pairs AS (SELECT c.course_name AS first_course, LEAD(c.course_name) OVER (PARTITION BY c.user_id ORDER BY c.completion_date, c.course_id) AS second_course FROM course_completions c JOIN top_students t ON t.user_id = c.user_id)
SELECT first_course, second_course, COUNT(*) AS transition_count FROM pairs WHERE second_course IS NOT NULL GROUP BY first_course, second_course ORDER BY transition_count DESC, first_course, second_course;
